// StudentActivity Backs G-07's "Hoạt động" column, which has three renderings and needs
// two facts to pick between them: "đang làm bài" while an attempt is live,
// a relative time when there is a last one, and an em dash when the student
// has never started anything.
//
// `live` is not `lastAttemptAt is recent`. Nothing in this system flips an
// attempt when its deadline passes -- assignment status is derived for
// exactly that reason (D-18) -- so a stale in-progress row would read as
// "đang làm bài" forever. The server ANDs the status with `deadline_at`.
type StudentActivity struct {
	LastAttemptAt *time.Time `json:"lastAttemptAt,omitempty"`

	// Live An attempt is in progress and inside its deadline.
	Live bool `json:"live"`
}

// StudentAssignmentCard `status`, `closesAt`, `durationMinutes` and `maxAttempts` are the
// signed-in student's own: when a teacher has given this student an
// override, they are the later close, the longer time limit and the added
// attempts (T-R4.12), and an assignment that closed for everyone else
// reads `open` here while the student's close is still ahead. Nothing in
// the card says an override exists or why.
type StudentAssignmentCard struct {
	AttemptsUsed int `json:"attemptsUsed"`

	// ClassId The id behind `className`, so S-17 can count a class's papers. Null when `className` is.
	ClassId *openapi_types.UUID `json:"classId,omitempty"`

	// ClassIds Every class this assignment targets that contains the student and is not archived, so each class card can name its next paper. Empty for a student targeted only by name.
	ClassIds *[]Uuid `json:"classIds,omitempty"`

	// ClassName The class this assignment reached the student through. Null unless exactly one targeted class that is not archived contains them.
	ClassName *string `json:"className,omitempty"`

	// ClosesAt RFC 3339, UTC. Rendered in `Asia/Ho_Chi_Minh` by the client.
	ClosesAt        Timestamp `json:"closesAt"`
	DurationMinutes int       `json:"durationMinutes"`

	// HasLiveAttempt Drives Start vs Resume (§9).
	HasLiveAttempt *bool `json:"hasLiveAttempt,omitempty"`

	// Id uuidv7 — time-ordered, so `id DESC` is a valid recency sort (§13.2).
	//
	// Examples: 019535d9-3df7-79fb-b466-fa907fa17f9e
	Id            Uuid                `json:"id"`
	LastAttemptId *openapi_types.UUID `json:"lastAttemptId,omitempty"`

	// LastSubmittedAt When the last attempt was handed in. Null while it is in progress.
	LastSubmittedAt *time.Time `json:"lastSubmittedAt,omitempty"`

	// LiveAnsweredCount How many of the live attempt's saved answers say something, by the rule the engine's navigator uses: a choice with an option picked, a true/false with a value, a text that is not blank, a fill-in with every blank filled. An answer that exists only in the browser's draft is not counted. Absent exactly when `hasLiveAttempt` is false.
	LiveAnsweredCount *int `json:"liveAnsweredCount,omitempty"`

	// LiveDeadlineAt The live attempt's deadline. Absent exactly when `hasLiveAttempt` is false.
	LiveDeadlineAt *time.Time `json:"liveDeadlineAt,omitempty"`
	MaxAttempts    int        `json:"maxAttempts"`

	// OpensAt RFC 3339, UTC. Rendered in `Asia/Ho_Chi_Minh` by the client.
	OpensAt Timestamp `json:"opensAt"`

	// QuestionCount Questions on the pinned version.
	QuestionCount int `json:"questionCount"`

	// Score Only when the assignment's `review.showScore` is on.
	Score *AttemptScore `json:"score,omitempty"`

	// Status **Derived**, never stored (D-18). A pure function of `publishedAt`,
	// `opensAt`, `closesAt` and an optional early `closedAt`, so it cannot go
	// stale and needs no scheduler.
	//
	// `draft` is what an unpublished assignment reads as. It does not weaken
	// D-18: publishing is an explicit act by the teacher, not a timestamp
	// arriving, so nothing has to flip a row on a schedule. A draft is
	// invisible to students and counts towards nothing.
	Status    AssignmentStatus `json:"status"`
	TestTitle string           `json:"testTitle"`

	// TotalPoints What the paper is out of.
	TotalPoints Points `json:"totalPoints"`
}

